    # For speed and determinism, compute savings only with nearest neighbors if provided
    nn = instance.get("nearest_neighbors", {})
    nn_key = "k"
    # If nearest_neighbors is dict[str, list[int]], we don't rely on str; use default fully-connected savings.
    use_nn = False
    if isinstance(nn, dict) and nn:
        # Determine whether nn provides a list per customer: if keys are present
        # We'll just avoid any key access that might be non-deterministic; fallback to full savings.
        use_nn = False

    savings = []
    if not use_nn:
        for i in cust_list:
            for j in cust_list:
                if i == j:
                    continue
                s = matrix[depot][i] + matrix[depot][j] - matrix[i][j]
                # deterministic tie-break: higher savings first, then i, then j
                savings.append((s, i, j))
        savings.sort(key=lambda t: (-t[0], t[1], t[2]))
    else:
        # not expected; keep safe fallback
        for i in cust_list:
            for j in cust_list:
                if i == j:
                    continue
                s = matrix[depot][i] + matrix[depot][j] - matrix[i][j]
                savings.append((s, i, j))
        savings.sort(key=lambda t: (-t[0], t[1], t[2]))

    # merge loop
    for s, i, j in savings:
        ri = cust_route[i]
        rj = cust_route[j]
        if ri == rj:
            continue
        if loads[ri] + loads[rj] > capacity:
            continue
        ri_route = routes[ri]
        rj_route = routes[rj]
        # i must be at end of its route, j must be at start of its route
        if ri_route and ri_route[-1] == i and rj_route and rj_route[0] == j:
            # merge ri + rj
            new_route = ri_route + rj_route
            routes[ri] = new_route
            loads[ri] = loads[ri] + loads[rj]
            routes[rj] = []
            # update mappings for all customers in merged route (deterministic but O(n^2) acceptable)
            for pos, c in enumerate(routes[ri]):
                cust_route[c] = ri
                cust_pos[c] = pos

    # remove empty routes and ensure feasibility (it should be by construction)
    routes = [r for r in routes if r]
    loads = [route_load(r) for r in routes]

    # --- Repair: ensure all customers are served exactly once ---
    # If any customer missing (shouldn't happen), reinsert greedily to first feasible route end.
    served = set()
    for r in routes:
        for v in r:
            served.add(v)
    missing = [c for c in customer_ids if c not in served]
    if missing:
        for c in missing:
            placed = False
            # try best insertion among existing routes, then empty route (none)
            best = None  # (delta, ri, inspos)
            for ri in range(len(routes)):
                if loads[ri] + demands[c] > capacity:
                    continue
                target = routes[ri]
                m = len(target)
                # find best insertion position in target
                for ins in range(m + 1):
                    if ins == 0:
                        if m == 0:
                            add = matrix[depot][c] + matrix[c][depot]
                        else:
                            add = matrix[depot][c] + matrix[c][target[0]] - matrix[depot][target[0]]
                    elif ins == m:
                        add = matrix[target[m - 1]][c] + matrix[c][depot] - matrix[target[m - 1]][depot]
                    else:
                        a = target[ins - 1]
                        b = target[ins]
                        add = matrix[a][c] + matrix[c][b] - matrix[a][b]
                    if best is None or add < best[0]:
                        best = (add, ri, ins)
            if best is not None:
                _, ri, ins = best
                routes[ri].insert(ins, c)
                loads[ri] += demands[c]
                placed = True
            if not placed:
                routes.append([c])
                loads.append(demands[c])

    # --- Local search: deterministic 2-opt and relocate ---
    # Bounded iterations; no randomness.
    # Keep small to avoid destabilizing feasibility.
    max_ls = 6
    for _it in range(max_ls):
        improved = False
        if len(routes) > 0:
            if two_opt_within(routes, loads):
                improved = True
        # relocation pass: stop after first improving move per iteration
        if relocate_once(routes, loads):
            improved = True
        if not improved:
            break

    # Final cleanup: ensure no route violates capacity; if so, split deterministically
    # (rare; keep safe)
    fixed_routes = []
    for r in routes:
        if not r:
            continue
        cur = []
        load = 0
        for v in r:
            if load + demands[v] <= capacity:
                cur.append(v)
                load += demands[v]
            else:
                fixed_routes.append(cur)
                cur = [v]
                load = demands[v]
        if cur:
            fixed_routes.append(cur)
    # If we had splitting, might create empty but handled.

    # Return routes (without depot, already ensured)
    return fixed_routes
